"""Guardian-owned reusable history chart with timeline event overlays."""

from __future__ import annotations

from html import escape


def render_history_html(*, configuration_path: str, maintenance_path: str,
                        timeline_path: str) -> str:
    paths = [escape(value, quote=True) for value in
             (configuration_path, maintenance_path, timeline_path)]
    return f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Guardian Zeitverläufe</title><style>:root{{color-scheme:light dark;--blue:#0d47a1;--card:var(--card-background-color,#fff)}}*{{box-sizing:border-box}}body{{margin:0;font:14px system-ui;background:var(--primary-background-color,#f5f6f8);color:var(--primary-text-color,#222)}}header{{padding:18px 22px;background:var(--blue);color:white}}nav{{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}}nav a{{color:white;text-decoration:none;padding:8px 12px;border:1px solid #ffffff66;border-radius:8px}}nav a.active{{background:white;color:var(--blue)}}main{{max-width:1100px;margin:auto;padding:16px}}.panel,.chart-card{{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 1px 5px #0002;margin-bottom:14px}}form{{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:10px;align-items:end}}label{{display:grid;gap:4px}}input,select,button{{font:inherit;padding:9px;border:1px solid #8888;border-radius:8px;background:transparent;color:inherit;min-width:0}}button{{cursor:pointer}}button.primary{{background:#1976d2;color:white;border:0}}.chart-wrap{{position:relative;width:100%;height:330px;overflow:hidden}}svg{{width:100%;height:100%;display:block}}.axis{{stroke:#78909c;stroke-width:1}}.series{{fill:none;stroke:#1976d2;stroke-width:2;vector-effect:non-scaling-stroke}}.markers{{position:absolute;inset:18px 12px 38px 48px;pointer-events:none}}.marker{{position:absolute;top:0;height:100%;width:2px;border:0;padding:0;background:#ef6c00;overflow:visible;pointer-events:auto;cursor:pointer}}.marker:before{{content:'🔧';position:absolute;top:calc(var(--lane)*28px);left:50%;transform:translateX(-50%);font-size:18px;background:var(--card);border-radius:50%}}.marker:focus{{outline:3px solid #1976d2;outline-offset:3px}}.detail{{margin-top:10px;padding:10px;border-left:4px solid #ef6c00;background:#ef6c0014}}.detail a{{display:inline-block;margin-top:6px}}.muted{{opacity:.72}}.error{{padding:10px;border-left:4px solid #d32f2f;background:#d32f2f18}}@media(max-width:760px){{form{{grid-template-columns:repeat(2,minmax(0,1fr))}}}}@media(max-width:520px){{main{{padding:10px}}form{{grid-template-columns:1fr}}.chart-wrap{{height:270px}}.markers{{inset:18px 8px 38px 38px}}}}</style></head><body><header><h1>Guardian Battery</h1><div>Messverläufe mit zeitlichem Maintenance-Kontext</div><nav><a href="{paths[0]}">Konfiguration</a><a href="{paths[1]}">Maintenance-Logbuch</a><a href="{paths[2]}">Verlauf</a><a class="active" href="history">Zeitverläufe</a></nav></header><main><section class="panel"><h2>Guardian-Zeitverlauf</h2><p>Messwerte und Marker bleiben getrennte Quellen. Die gemeinsame Ansicht zeigt zeitliche Korrelation, keine Kausalität.</p><form id="controls"><label>Messgröße<select id="metric"><option value="soc">SOC [%]</option><option value="current">Strom [A]</option><option value="cell_voltage">Zellspannung [mV]</option><option value="cell_temperature">Zelltemperatur [°C]</option></select></label><label>Modul<select id="module"></select></label><label id="cell-label" hidden>Zelle<select id="cell"></select></label><label>Von<input id="from" type="datetime-local" required></label><label>Bis<input id="to" type="datetime-local" required></label><label>Archiv<select id="archived"><option value="false">Archivierte ausblenden</option><option value="true">Archivierte anzeigen</option></select></label><button class="primary" type="submit">Zeitfenster laden</button></form><p class="muted">Zeiten werden lokal angezeigt und für API und Markerfenster nach UTC konvertiert.</p></section><div id="message" role="status"></div><section class="chart-card"><h2 id="chart-title">SOC</h2><div class="chart-wrap"><svg id="chart" viewBox="0 0 1000 300" preserveAspectRatio="none" aria-label="Zeitreihe"></svg><div id="markers" class="markers"></div></div><div id="marker-detail" class="detail" hidden><strong id="marker-title"></strong><div id="marker-meta"></div><a id="marker-link">Maintenance-Eintrag öffnen</a></div><p id="empty" class="muted"></p></section><script>const byId=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';function localInput(iso){{const d=new Date(iso),p=n=>String(n).padStart(2,'0');return `${{d.getFullYear()}}-${{p(d.getMonth()+1)}}-${{p(d.getDate())}}T${{p(d.getHours())}}:${{p(d.getMinutes())}}`}}function utc(v){{const p=v.match(/[0-9]+/g).map(Number),d=new Date(p[0],p[1]-1,p[2],p[3],p[4]);if(d.getFullYear()!=p[0]||d.getMonth()!=p[1]-1||d.getDate()!=p[2]||d.getHours()!=p[3]||d.getMinutes()!=p[4])throw Error('Diese lokale Uhrzeit existiert wegen einer Zeitumstellung nicht.');return d.toISOString()}}function options(id,max){{for(let n=1;n<=max;n++){{const o=document.createElement('option');o.value=String(n);o.textContent=String(n);byId(id).append(o)}}}}function query(){{const q=new URLSearchParams({{metric:byId('metric').value,module_number:byId('module').value,from:utc(byId('from').value),to:utc(byId('to').value),include_archived:byId('archived').value}});if(byId('metric').value.startsWith('cell_'))q.set('cell_number',byId('cell').value);return q}}function svg(name,attrs){{const n=document.createElementNS(NS,name);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,String(v));return n}}function renderSeries(data){{const chart=byId('chart');chart.replaceChildren();chart.append(svg('line',{{x1:45,y1:15,x2:45,y2:265,class:'axis'}}),svg('line',{{x1:45,y1:265,x2:990,y2:265,class:'axis'}}));const points=data.series.points;byId('empty').textContent=points.length?'': 'Keine Messpunkte in diesem Zeitfenster.';if(!points.length)return;const times=points.map(p=>new Date(p.timestamp).getTime()),values=points.map(p=>p.value),t0=new Date(data.window.from).getTime(),t1=new Date(data.window.to).getTime(),min=Math.min(...values),max=Math.max(...values),span=max-min||1,tw=t1-t0||1;const coords=points.map((p,i)=>`${{45+(times[i]-t0)/tw*945}},${{265-(values[i]-min)/span*240}}`).join(' ');chart.append(svg('polyline',{{points:coords,class:'series'}}));const lo=svg('text',{{x:4,y:265}});lo.textContent=String(min);const hi=svg('text',{{x:4,y:25}});hi.textContent=String(max);chart.append(lo,hi)}}function showMarker(marker){{byId('marker-title').textContent=marker.title;const parts=['Maintenance',new Intl.DateTimeFormat('de-DE',{{dateStyle:'medium',timeStyle:'short'}}).format(new Date(marker.timestamp)),marker.metadata.category,marker.module_number?'Modul '+marker.module_number:null,marker.cell_number?'Zelle '+marker.cell_number:null].filter(Boolean);byId('marker-meta').textContent=parts.join(' · ');byId('marker-link').href=marker.deep_link;byId('marker-detail').hidden=false}}function renderMarkers(markers){{const root=byId('markers');root.replaceChildren();markers.forEach((marker,index)=>{{const button=document.createElement('button');button.type='button';button.className='marker';button.style.left=`${{marker.position*100}}%`;button.style.setProperty('--lane',String(index%4));button.setAttribute('aria-label',`Maintenance: ${{marker.title}}`);button.onclick=()=>showMarker(marker);root.append(button)}})}}async function load(e){{e?.preventDefault();byId('message').replaceChildren();byId('marker-detail').hidden=true;try{{const r=await fetch('api/history/series?'+query()),data=await r.json();if(!r.ok)throw Error(data.error?.message||'Zeitverlauf nicht verfügbar');byId('chart-title').textContent=byId('metric').selectedOptions[0].textContent;renderSeries(data);renderMarkers(data.overlays)}}catch(error){{const b=document.createElement('div');b.className='error';b.textContent=error.message;byId('message').append(b);byId('chart').replaceChildren();byId('markers').replaceChildren()}}}}function metricChanged(){{byId('cell-label').hidden=!byId('metric').value.startsWith('cell_')}}options('module',6);options('cell',15);const end=new Date(),start=new Date(end.getTime()-24*3600000);byId('from').value=localInput(start);byId('to').value=localInput(end);byId('metric').onchange=metricChanged;byId('controls').onsubmit=load;load();</script></main></body></html>'''
